package com.sehatharian;
import com.sehatharian.config.*;
import com.sehatharian.content.ContentService;
import com.sehatharian.content.ContentService.*;
import com.sehatharian.model.*;
import com.sehatharian.nutrition.*;
import com.sehatharian.repository.*;
import com.sehatharian.service.*;
import java.time.*;
import java.util.*;
import java.sql.*;

/** Opt-in destructive fixture creation is restricted to a disposable test schema. */
public final class RombakIntegration {
    private static int checks;
    private static void ok(boolean condition,String label){if(!condition)throw new AssertionError(label);System.out.println("PASS "+(++checks)+" "+label);}
    private static void rejected(Throwing run,String label)throws Exception{try{run.run();}catch(SecurityException|IllegalArgumentException|IllegalStateException expected){ok(true,label);return;}throw new AssertionError(label);}
    private interface Throwing{void run()throws Exception;}
    private static long scalar(String sql)throws Exception{try(var c=DatabaseConfig.getConnection();var s=c.createStatement();var r=s.executeQuery(sql)){r.next();return r.getLong(1);}}
    public static void main(String[] args)throws Exception {
        if(!System.getenv("DB_NAME").matches("sehatharian_test_rombak_[a-z0-9_]+"))throw new SecurityException("Dedicated test schema required");
        DatabaseBootstrap.initialize();long legacy=scalar("SELECT COUNT(*) FROM jadwal_tidur");DatabaseBootstrap.initialize();ok(legacy==scalar("SELECT COUNT(*) FROM jadwal_tidur"),"additive migration preserves legacy schedules");ok(scalar("SELECT COUNT(*) FROM sleep_actual")==0,"legacy schedule never becomes actual sleep");
        UserSession a=new UserSession(),b=new UserSession(),admin=new UserSession();AuthService aa=new AuthService(new PenggunaRepository(),a),bb=new AuthService(new PenggunaRepository(),b);
        aa.register("Fixture Alpha","alpha@example.test","fixture123","fixture123");bb.register("Fixture Beta","beta@example.test","fixture123","fixture123");aa.login("alpha@example.test","fixture123");bb.login("beta@example.test","fixture123");ok(!a.isAdmin(),"public registration stays user");
        try(var c=DatabaseConfig.getConnection();var p=c.prepareStatement("INSERT INTO pengguna(nama,email,password_hash,role,onboarding_selesai) VALUES('Fixture Admin','admin@example.test',?,'admin',TRUE)")){p.setString(1,com.sehatharian.util.PasswordUtil.hashPassword("fixture123"));p.executeUpdate();}
        new AuthService(new PenggunaRepository(),admin).login("admin@example.test","fixture123");SessionAccess ax=new SessionAccess(a),bx=new SessionAccess(b),ad=new SessionAccess(admin);
        var cms=new ContentService(ad);rejected(()->new ContentService(ax).adminList(Kind.PROGRAM,""),"user cannot read drafts");rejected(()->new ContentService(ax).saveDraft(null,Kind.EDUCATION,"No","No",List.of()),"user cannot edit content");
        int movement=cms.saveDraft(null,Kind.MOVEMENT,"Jalan Kaki","team-walking",List.of());rejected(()->cms.transition(movement,State.PUBLISHED),"publish cannot skip review");cms.transition(movement,State.REVIEWED);cms.transition(movement,State.PUBLISHED);
        int program=cms.saveDraft(null,Kind.PROGRAM,"Program Uji","Video tim 60 detik",List.of(new Step(movement,60,false)));cms.transition(program,State.REVIEWED);cms.transition(program,State.PUBLISHED);ok(new ContentService(ax).publishedProgram(program).steps().size()==1,"user sees published program and ordered steps");rejected(()->cms.transition(movement,State.ARCHIVED),"published program blocks movement archive");
        int revision=cms.saveDraft(movement,Kind.MOVEMENT,"Jalan Kaki revisi","team-walking",List.of());ok(new ContentService(ax).published(Kind.MOVEMENT).getFirst().id()==movement,"draft revision retains current public version");cms.transition(revision,State.REVIEWED);cms.transition(revision,State.PUBLISHED);ok(new ContentService(ax).movementForPublishedStep(program,movement).state()==State.SUPERSEDED,"existing program retains referenced old movement version");
        var today=LocalDate.now(ZoneId.of("Asia/Jakarta"));var habits=new KebiasaanService(ax);long before=scalar("SELECT COUNT(*) FROM aktivitas WHERE pengguna_id="+a.getUserId());
        java.util.concurrent.atomic.AtomicLong nanos=new java.util.concurrent.atomic.AtomicLong();var engine=new com.sehatharian.training.TrainingSession(List.of(new com.sehatharian.training.TrainingSession.Step(com.sehatharian.catalog.TeamExercises.ALL.get(2).exercise(),false,60)),0,0,nanos::get);engine.start();engine.pulse(engine.revision());engine.advance(engine.revision(),false);
        for(int i=0;i<60;i++){nanos.addAndGet(1_000_000_000L);engine.pulse(engine.revision());}engine.advance(engine.revision(),false);ok(engine.activeSeconds()==60&&scalar("SELECT COUNT(*) FROM aktivitas WHERE pengguna_id="+a.getUserId())==before,"timer reaches summary without implicit activity write");habits.tambahAktivitas(a.getUserId(),today,"Latihan video tim",1,"Aktif 60 detik");ok(scalar("SELECT COUNT(*) FROM aktivitas WHERE pengguna_id="+a.getUserId())==before+1,"explicit save writes exactly one activity");ok(new KebiasaanService(bx).getAktivitasHariIni(b.getUserId(),today).isEmpty(),"two SQL sessions isolate activity");
        FoodImport.main(new String[]{".runtime/foods.xml"});long foods=scalar("SELECT COUNT(*) FROM food_catalog");FoodImport.main(new String[]{".runtime/foods.xml"});ok(foods==7795&&foods==scalar("SELECT COUNT(*) FROM food_catalog"),"repeat food import does not duplicate 7795 items");
        NutritionService nutrition=new NutritionService(ax);var food=nutrition.search("Baked potato").getFirst();int meal=nutrition.save(today,"sarapan",food.id(),150);var snapshot=nutrition.history(today).stream().filter(m->m.id()==meal).findFirst().orElseThrow();ok(snapshot.nutrients().values().get("calories")==food.nutrients().values().get("calories")*1.5,"150g food calculation stored correctly");try(var c=DatabaseConfig.getConnection();var p=c.prepareStatement("UPDATE food_catalog SET nutrients='calories=999',version='changed' WHERE food_id=?")){p.setString(1,food.id());p.executeUpdate();}ok(nutrition.history(today).stream().filter(m->m.id()==meal).findFirst().orElseThrow().nutrients().equals(snapshot.nutrients()),"catalog revision cannot change food history");rejected(()->nutrition.save(today,"sarapan",food.id(),Double.NaN),"invalid food portion rejected");
        habits.tambahHidrasi(a.getUserId(),today,500,"fixture");ok(habits.getTotalHidrasiMl(a.getUserId(),today)==500,"hydration persists");var sleeps=new ActualSleepRepository(ax);sleeps.record(today.minusDays(1).atTime(23,0),today.atTime(3,0));ok(sleeps.getByRange(a.getUserId(),today,today).getFirst().getDurasiJam()==4,"midnight sleep and wake date correct");ok(scalar("SELECT COUNT(*) FROM sleep_actual WHERE trigger_name='tidur_kurang' AND pengguna_id="+a.getUserId())==1,"short actual sleep fires project trigger");rejected(()->sleeps.record(today.minusDays(1).atTime(23,30),today.atTime(3,30)),"overlapping sleep rejected");
        int challenge=cms.saveDraft(null,Kind.CHALLENGE,"Air 500 ml","hydration|500",List.of());cms.transition(challenge,State.REVIEWED);cms.transition(challenge,State.PUBLISHED);var challenges=new HabitChallengeService(ax);int joined=challenges.join(challenge,today);challenges.evaluate(joined);ok(challenges.history(today).getFirst().complete(),"challenge completion reads persisted hydration");
        int unfinished=cms.saveDraft(null,Kind.CHALLENGE,"Air 1000 ml","hydration|1000",List.of());cms.transition(unfinished,State.REVIEWED);cms.transition(unfinished,State.PUBLISHED);int insufficient=challenges.join(unfinished,today);rejected(()->challenges.evaluate(insufficient),"challenge cannot complete below recorded target");
        var insights=new HabitInsights(ax);ok(!insights.advise("activity",today).state().equals("READY"),"incomplete profile prevents personal advice");new PenggunaRepository().updateOnboarding(a.getUserId(),30,"dalam_rumah","dewasa",true,ax);ok(insights.advise("activity",today).state().equals("INSUFFICIENT"),"one recorded day prevents personal advice");for(int i=1;i<3;i++)habits.tambahAktivitas(a.getUserId(),today.minusDays(i),"Jalan kaki",20,"fixture");ok(insights.advise("activity",today).state().equals("READY"),"three saved days and profile enable explained advice");ok(insights.days(today,7).values().stream().filter(m->m.containsKey("activity")).count()==3,"progress retains missing days as gaps");
        aa.logout();ok(b.isLoggedIn(),"logout A preserves B session");rejected(()->nutrition.search("potato"),"old user action rejected after logout");admin.logout();rejected(()->cms.transition(program,State.ARCHIVED),"old admin action rejected after logout");
        System.out.println("ALL "+checks+" INTEGRATION CHECKS PASSED on "+System.getenv("DB_NAME"));
    }
}
